---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Account table: Customer accounts with health, plan and an agent note per row.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change account-table.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './account-table.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="account-table" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="atb panel">
  <div class="atb-h"><div class="atb-s"><svg class="i xs"><use href="#i-search"/></svg><input placeholder="Search accounts" aria-label="Search accounts"></div><div class="atb-fl" role="group" aria-label="Plan"><button class="chip sm on" data-p="" aria-pressed="true">All</button><button class="chip sm" data-p="Team" aria-pressed="false">Team</button><button class="chip sm" data-p="Pro" aria-pressed="false">Pro</button><button class="chip sm" data-p="Enterprise" aria-pressed="false">Enterprise</button></div></div>
  <div class="atb-sc"><table><thead><tr><th>Account</th><th>Plan</th><th class="r">Seats</th><th>Health</th><th class="r">MRR</th></tr></thead><tbody></tbody></table></div>
</div>
  </Fragment></div>
</div>
<script>
  import './account-table.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Account table ---------- */
/* the account table's colours run brighter than the shared tones: its plan tags take a stronger tint with saturated text
   (4.5:1 and APCA Lc 60 on the tint, in every style and theme) and the health bars vivid marks (3:1) */
.atb{--dm-atb-ok:#1daa51;--dm-atb-warn:#cd7a00;--dm-atb-bad:#f04438;
  --dm-pb:#0663d2;--dm-pb-bg:color-mix(in srgb,#4890fa 15%,transparent);--dm-pl:#7d2dfc;--dm-pl-bg:color-mix(in srgb,#9776fa 15%,transparent);--dm-pm:#087744;--dm-pm-bg:color-mix(in srgb,#1fad66 15%,transparent);--dm-pp:#a34f06;--dm-pp-bg:color-mix(in srgb,#dc7019 15%,transparent);
  --dm-pr:#c50b2d;--dm-pr-bg:color-mix(in srgb,#fb4652 15%,transparent);--dm-py:#886006;--dm-py-bg:color-mix(in srgb,#bb881a 15%,transparent);--dm-pk:#b80a75;--dm-pk-bg:color-mix(in srgb,#fb27a2 15%,transparent);--dm-pt:#08727c;--dm-pt-bg:color-mix(in srgb,#1fa5b1 15%,transparent)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .atb{--dm-atb-ok:#5fcb2a;--dm-atb-warn:#f59e0b;--dm-atb-bad:#fb4849;
  --dm-pb:#a4c9fe;--dm-pb-bg:color-mix(in srgb,#4890fa 22%,transparent);--dm-pl:#c9befe;--dm-pl-bg:color-mix(in srgb,#9776fa 22%,transparent);--dm-pm:#19e285;--dm-pm-bg:color-mix(in srgb,#1fad66 22%,transparent);--dm-pp:#feb68b;--dm-pp-bg:color-mix(in srgb,#dc7019 22%,transparent);
  --dm-pr:#feb1ad;--dm-pr-bg:color-mix(in srgb,#fb4652 22%,transparent);--dm-py:#feba28;--dm-py-bg:color-mix(in srgb,#bb881a 22%,transparent);--dm-pk:#feabcf;--dm-pk-bg:color-mix(in srgb,#fb27a2 22%,transparent);--dm-pt:#19daeb;--dm-pt-bg:color-mix(in srgb,#1fa5b1 22%,transparent)}}
:root[data-theme="dark"] .atb{--dm-atb-ok:#5fcb2a;--dm-atb-warn:#f59e0b;--dm-atb-bad:#fb4849;
  --dm-pb:#a4c9fe;--dm-pb-bg:color-mix(in srgb,#4890fa 22%,transparent);--dm-pl:#c9befe;--dm-pl-bg:color-mix(in srgb,#9776fa 22%,transparent);--dm-pm:#19e285;--dm-pm-bg:color-mix(in srgb,#1fad66 22%,transparent);--dm-pp:#feb68b;--dm-pp-bg:color-mix(in srgb,#dc7019 22%,transparent);
  --dm-pr:#feb1ad;--dm-pr-bg:color-mix(in srgb,#fb4652 22%,transparent);--dm-py:#feba28;--dm-py-bg:color-mix(in srgb,#bb881a 22%,transparent);--dm-pk:#feabcf;--dm-pk-bg:color-mix(in srgb,#fb27a2 22%,transparent);--dm-pt:#19daeb;--dm-pt-bg:color-mix(in srgb,#1fa5b1 22%,transparent)}
/* the search and the plan filters: 16px in from the card's edges, the last filter ending on the content's right edge. The
   field's glass sits in the logos' column and its words start on the names' column, as the rows under it do */
.atb-h{display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-4) var(--dm-s-4) var(--dm-s-3);flex-wrap:wrap;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* a narrow card (a phone): the search takes the width and the filters go under it, on its left edge */
.atb{container-type:inline-size}
@container (max-width:420px){.atb-h{flex-direction:column;align-items:stretch}.atb-h>.atb-s{flex:none;min-width:0}}
.atb-s{display:flex;align-items:center;gap:var(--dm-s-4);height:32px;padding:0 10px 0 6px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);color:var(--dm-muted);flex:1;min-width:160px;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.atb-s{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.atb-s input{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--dm-fg)}
.atb-s:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.atb-s input::placeholder{color:var(--dm-muted)}
.atb-fl{display:flex;gap:var(--dm-s-1);flex-wrap:wrap}
/* the filters are white chips with a dimmed grey edge; the picked one's edge is a step stronger */
.atb-fl .chip{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent)}
@media (hover:hover) and (pointer:fine){.atb-fl .chip:hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent)}}
/* the table sits 8px in from the card's sides, and its first and last cells keep 8px more: every column's words start where
   its head's words start, the first 16px in and the last ending 16px from the right, and a row's hover fill reaches 8px out
   round them with rounded corners, in place of the hairlines round it (owner, 18 Nov). On a phone the table scrolls sideways */
/* the rows' fills reach as far toward the foot as toward the sides: 8px */
.atb-sc{overflow-x:auto;padding:0 var(--dm-s-2) var(--dm-s-2)}
.atb table{width:100%;border-collapse:separate;border-spacing:0;font-size:13px;min-width:560px}
.atb th{text-align:left;font-weight:500;font-size:12px;line-height:18px;color:var(--dm-muted);padding:10px var(--dm-s-3);white-space:nowrap}
.atb th.r,.atb td.r{text-align:right}
/* it reads as a table of columns (owner, 10 and 21 Nov): a hairline after every column but the last, in every style and
   wherever the columns have been moved; the note under a row spans them all with none. The columns resize and move as in a
   spreadsheet (cols()): a header takes the keyboard's focus so Alt and an arrow can move it, and sized by hand, a cell too
   narrow for its words cuts them short */
.atb{--dm-atb-col:color-mix(in srgb,color-mix(in srgb,var(--dm-line),var(--dm-fg) 9%) 50%,transparent)}
.atb :is(th,td):not(:last-child){box-shadow:inset -1px 0 0 var(--dm-atb-col)}
.atb th{position:relative}
.atb th[tabindex]:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-xs)}
.atb table.cols-rz td{overflow:hidden;text-overflow:ellipsis}
.atb td{padding:10px var(--dm-s-3);line-height:20px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);white-space:nowrap;transition:background-color var(--dm-t-fast) var(--dm-ease)}
.atb :is(th,td):first-child{padding-left:var(--dm-s-2)}
.atb :is(th,td):last-child{padding-right:var(--dm-s-2)}
.atb tr.row{cursor:pointer}
@media (hover:hover) and (pointer:fine){
  .atb tr.row:hover td{background:color-mix(in srgb,var(--dm-fg) 4%,transparent);border-top-color:transparent}
  .atb tr.row:hover td:first-child{border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk))) 0 0 calc(8px * var(--dm-rk-m,var(--dm-rk)))}
  .atb tr.row:hover td:last-child{border-radius:0 calc(8px * var(--dm-rk-m,var(--dm-rk))) calc(8px * var(--dm-rk-m,var(--dm-rk))) 0}
  .atb tr.row:hover+tr td{border-top-color:transparent}
}
/* a row that takes the focus fills the scrolling table, which would cut an outside ring: its ring is drawn inside */
.atb tr.row:focus-visible{outline-offset:-2px}
.atb .nm{display:flex;align-items:center;gap:10px;font-weight:500}
/* brand tiles sit a shade darker than the brand colour, so their white letter reads at 4.5:1 or more */
.atb .lg{width:24px;height:24px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;font-size:10px;font-weight:500;color:#fff}
.atb .hb{display:flex;align-items:center;gap:var(--dm-s-2)}
.atb .hb i{width:54px;height:5px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-line);overflow:hidden;display:block}
.atb .hb i b{display:block;height:100%;border-radius:var(--dm-r-tiny,3px)}
.atb .hb span{font-size:12px;color:var(--dm-fg2)}
/* the agent's note opens under its row, with no hairline between them: the spark centred under the logos, the words on the
   names' column, and its button ending where MRR ends, centred on the words */
.atb tr.det td{padding:0;border-top:0}
/* the note is a detail row under its account (owner, 21 Nov): it spans every column, so the column lines stop at its top edge and
   start again under it, and it sits in an inset panel of the style's quiet fill (Clean: its off-white with 10px corners), its
   spark under the logos and its words on the names' column; the account it belongs to keeps a quiet fill while it is open */
.atb-note{display:flex;align-items:center;gap:var(--dm-s-3);margin:0 0 var(--dm-s-2);padding:10px var(--dm-s-2) 10px 14px;border-radius:var(--dm-r-in);background:var(--dm-wash);font-size:12.5px;line-height:1.5;color:var(--dm-fg2);white-space:normal}
.atb-note>svg{color:var(--dm-accent-mark,var(--dm-accent));flex:none;margin-right:4px}
.atb-note span{flex:1}
/* Draft email is as wide as its words, and eases to the new width as it says Drafting, then Draft ready with the green tick */
.atb-note .pill{flex:none;overflow:hidden}
.atb-note .pill .spin{width:12px;height:12px}
.atb-note .pill .atb-done{display:grid;color:var(--dm-ok-mark)}
/* nothing matches: the empty state of the lab's Clean (lab/clean), in every style. A small sketch of a table on a white card,
   what happened, one muted line and the way back to every account */
.atb-empty td{padding:28px var(--dm-s-4) 30px;text-align:center;white-space:normal}
.atb-em{display:flex;flex-direction:column;align-items:center;gap:4px}
.atb-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.atb-em>span:not(.atb-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.atb-em .pill{margin-top:12px}
.atb-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 16px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.atb-em-art::before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 60%,var(--dm-surface)))}
.atb-em-art::after{content:"";position:absolute;left:32px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 60%,var(--dm-surface)))}
/* Clean: the same 16px insets, the spark the quiet grey of Clean's chrome */
:root[data-style="clean"] .atb-note>svg,:root [data-style="clean"] .atb-note>svg,:root [data-style="clean"].atb-note>svg{color:var(--dm-fg2)}
:root[data-style="clean"] .atb-note,:root [data-style="clean"] .atb-note,:root [data-style="clean"].atb-note{border-radius:10px;background:var(--dm-strip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
.atb tr.row.open td{background:var(--dm-row);border-top-color:transparent}
.atb tr.row.open td:first-child{border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk))) 0 0 calc(8px * var(--dm-rk-m,var(--dm-rk)))}
.atb tr.row.open td:last-child{border-radius:0 calc(8px * var(--dm-rk-m,var(--dm-rk))) calc(8px * var(--dm-rk-m,var(--dm-rk))) 0}
/* Clean: the search and the plan filters sit in the card's off-white head strip, with a hairline under it (owner, 21 Nov: "add
   a gray background behind the search accounts"), 16px in at the sides and 8px from its top and bottom */
:root[data-style="clean"] .atb-h,:root [data-style="clean"] .atb-h,:root [data-style="clean"].atb-h{padding:8px 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, cols, enter, html, reflow, stagger } from '../core/core.js';
DM.def('account-table', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{search}', I('search','xs'));
  const A = [
    ['Northwind','b','Enterprise',120,92,'$14,400','Expanding. Design team added 18 seats this month.'],
    ['Lumen Labs','l','Pro',14,48,'$672','Usage fell 40% after their lead designer left. Worth a check in.'],
    ['Fable & Co','m','Team',32,81,'$1,920','Steady. Asked about the Figma sync twice.'],
    ['Orbit','p','Pro',8,67,'$384','Trial of the agent ends Friday. 3 runs so far.'],
    ['Kite Health','r','Enterprise',64,88,'$7,680','Renewal in 6 weeks, champion is happy.'],
    ['Paper Plane','t','Team',21,34,'$1,260','Two failed payments. Billing contact bounced.']
  ];
  const tb = $('tbody', r), q = $('.atb-s input', r); let plan = '', open = null;
  const hc = h => h >= 80 ? 'var(--dm-atb-ok)' : h >= 60 ? 'var(--dm-atb-warn)' : 'var(--dm-atb-bad)';
  // each row is made once and kept, so a search or a plan filter can ease it between places; the note under an open row
  // is its own row, keyed after it
  const rows = new Map(A.map(a => [a[0], html(`<tr class="row" data-n="${a[0]}" tabindex="0" aria-expanded="false"><td><span class="nm"><span class="lg" style="background:var(--dm-av-${a[1]});color:var(--dm-av-${a[1]}-ink)">${a[0][0]}</span>${a[0]}</span></td><td><span class="tag ${a[2] === 'Enterprise' ? 'l' : a[2] === 'Pro' ? 'b' : 't'}">${a[2]}</span></td><td class="r num">${a[3]}</td><td><span class="hb"><i><b style="width:${a[4]}%;background:${hc(a[4])}"></b></i><span class="num">${a[4]}</span></span></td><td class="r num">${a[5]}</td></tr>`)]));
  const none = html('<tr class="atb-empty" data-n=" none"><td colspan="5"><div class="atb-em"><span class="atb-em-art" aria-hidden="true"></span><b>No accounts match</b><span>Try another name, or show every plan.</span><button class="pill soft sm">Show all accounts</button></div></td></tr>');
  $('.pill', none).onclick = () => { q.value = ''; plan = ''; pick($('.atb-fl .chip[data-p=""]', r)); paint(true); };
  let det = null;
  function note(a){
    const d = html(`<tr class="det" data-n="${a[0]} note"><td colspan="5"><div class="fold"><div><div class="atb-note">${I('spark','xs')}<span>${a[6]}</span><button class="pill soft sm">Draft email</button></div></div></div></td></tr>`);
    // pressed, it says Drafting with the loader's sweep, then Draft ready with the green tick; it is always as wide as its
    // words, easing to each new width, and never goes blank
    const dr = $('.pill', d);
    const label = h => { const w0 = dr.getBoundingClientRect().width; dr.innerHTML = h; const w1 = dr.getBoundingClientRect().width;
      if (!REDUCE && w0 && Math.abs(w1 - w0) > .5) dr.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:(parseFloat(getComputedStyle(dr).getPropertyValue('--dm-t')) || .45) * 1000, easing:getComputedStyle(dr).getPropertyValue('--dm-ease').trim() || 'ease' }); };
    dr.onclick = e => { e.stopPropagation(); if (dr.dataset.s) return; dr.dataset.s = 'busy'; label('<span class="spin"></span><span class="shim">Drafting</span>');
      c.later(900, () => { dr.dataset.s = 'done'; label(`<span class="atb-done">${I('check','xs')}</span>Draft ready`); }); };
    return d;
  }
  // the rows that match, in order, with the open row's note under it
  function paint(anim){
    const s = q.value.trim().toLowerCase(), L = A.filter(a => (!plan || a[2] === plan) && (!s || a[0].toLowerCase().includes(s)));
    // a note still folding shut stays under its row
    const draw = () => { const keep = $$('tr.det.going', tb); tb.replaceChildren(...(L.length ? L.flatMap(a => [rows.get(a[0]), ...(det && open === a[0] ? [det] : [])]) : [none]));
      keep.forEach(x => { if (x._row.isConnected) x._row.after(x); }); };
    if (anim) reflow(() => $$('tr[data-n]', tb), draw, { by:'data-n', root:$('.atb', r) }); else draw();
    rows.forEach((tr, n) => tr.classList.toggle('open', n === open));
  }
  // a row opens its note by its height, and the rows under it ease down; another row, or the same one again, folds it shut
  function toggle(n){
    if (det){ const d = det, f = $('.fold', d); d.classList.add('going'); d.removeAttribute('data-n'); f.classList.add('shut'); setTimeout(() => d.remove(), REDUCE ? 0 : (parseFloat(getComputedStyle(r).getPropertyValue('--dm-t')) || .45) * 1000); det = null; }
    open = open === n ? null : n;
    if (open){ det = note(A.find(a => a[0] === open)); det._row = rows.get(open); const f = $('.fold', det); f.classList.add('shut'); rows.get(open).after(det); void f.offsetHeight; f.classList.remove('shut'); enter($('.atb-note', det)); }
    rows.forEach((tr, k) => { tr.classList.toggle('open', k === open); tr.setAttribute('aria-expanded', k === open); });
  }
  // a row opens with a click, or with Enter or Space once it has the focus
  rows.forEach((tr, n) => { tr.onclick = () => toggle(n); tr.onkeydown = e => { if ((e.key === 'Enter' || e.key === ' ') && e.target === tr){ e.preventDefault(); toggle(n); } }; });
  q.oninput = () => paint(true);
  const pick = ch => $$('.atb-fl .chip', r).forEach(x => { x.classList.toggle('on', x === ch); x.setAttribute('aria-pressed', x === ch); });
  $$('.atb-fl .chip', r).forEach(ch => ch.onclick = () => { pick(ch); plan = ch.dataset.p; paint(true); });
  paint(); stagger([...rows.values()], 35);
  // the columns resize and move as in a spreadsheet (owner, 10 and 21 Nov); Account stays first, and every other header takes
  // the keyboard's focus, so Alt and an arrow move it
  $$('thead th', r).forEach((th, i) => { if (i) th.tabIndex = 0; });
  c.offs.push(cols($('table', r), { move:[1, 2, 3, 4], min:{ 0:150, 1:96, 2:72, 3:112, 4:88 } }));
  // the rows come in once: a row a search or a filter puts back glides to its place and never plays its entrance again (in
  // Clean and Blueprint the entrance runs under its own name, which enter() doesn't clear)
  rows.forEach(tr => { const done = e => { if (e.target !== tr) return; tr.classList.remove('enter'); tr.removeEventListener('animationend', done); }; tr.addEventListener('animationend', done); });
  // the preview opens one account's note on its own, unless you take over first
  c.auto(1200, () => { if (!open) toggle('Lumen Labs'); });
});
